'use strict';

// MODULES //
var tape = require( 'tape' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var Float32Array = require( '@stdlib/array/float32' );
var sstdevyc = require( './../lib/ndarray.js' );

// CONSTANTS //
var EPSILON = 1e-6; // Tolerance for floating-point comparisons

// TESTS //

tape( 'main export is a function', function test( t ) {
    t.ok( true, __filename );
    t.strictEqual( typeof sstdevyc, 'function', 'main export is a function' );
    t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
    t.strictEqual( sstdevyc.length, 5, 'has expected arity' );
    t.end();
});

tape( 'the function calculates the population standard deviation of a strided array', function test( t ) {
    var expected;
    var x;
    var v;

    x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] );
    v = sstdevyc( x.length, 0, x, 1, 0 );
    expected = float64ToFloat32( sqrt( 53.5 / x.length ) );
    t.ok( Math.abs( v - expected ) < EPSILON, 'returns expected value: ' + v );

    x = new Float32Array( [ -4.0, -4.0 ] );
    v = sstdevyc( x.length, 0, x, 1, 0 );
    t.strictEqual( v, 0.0, 'returns expected value for identical elements' );

    x = new Float32Array( [ NaN, 4.0 ] );
    v = sstdevyc( x.length, 0, x, 1, 0 );
    t.strictEqual( isnan( v ), true, 'returns NaN when input contains NaN' );

    t.end();
});

tape( 'the function calculates the sample standard deviation of a strided array', function test( t ) {
    var expected;
    var x;
    var v;

    x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] );
    v = sstdevyc( x.length, 1, x, 1, 0 );
    expected = float64ToFloat32( sqrt( 53.5 / (x.length - 1) ) );
    t.ok( Math.abs( v - expected ) < EPSILON, 'returns expected value: ' + v );

    x = new Float32Array( [ -4.0, -4.0 ] );
    v = sstdevyc( x.length, 1, x, 1, 0 );
    t.strictEqual( v, 0.0, 'returns expected value for identical elements' );

    x = new Float32Array( [ NaN, 4.0 ] );
    v = sstdevyc( x.length, 1, x, 1, 0 );
    t.strictEqual( isnan( v ), true, 'returns NaN when input contains NaN' );

    t.end();
});

tape( 'the function supports accessor arrays', function test( t ) {
    var expected;
    var x;
    var arr;
    var v;

    // Test with accessor array (population standard deviation)
    x = new Float32Array( [ 1.0, -2.0, -4.0, 5.0, 0.0, 3.0 ] );
    arr = {
        values: x,
        get: function( idx ) { return this.values[ idx ]; }
    };
    v = sstdevyc( arr.values.length, 0, arr, 1, 0 );
    expected = float64ToFloat32( sqrt( 53.5 / arr.values.length ) );
    t.ok( Math.abs( v - expected ) < EPSILON, 'returns expected value for accessor array (population): ' + v );

    // Test with accessor array (sample standard deviation)
    v = sstdevyc( arr.values.length, 1, arr, 1, 0 );
    expected = float64ToFloat32( sqrt( 53.5 / (arr.values.length - 1) ) );
    t.ok( Math.abs( v - expected ) < EPSILON, 'returns expected value for accessor array (sample): ' + v );

    // Test identical elements
    x = new Float32Array( [ -4.0, -4.0 ] );
    arr = {
        values: x,
        get: function( idx ) { return this.values[ idx ]; }
    };
    v = sstdevyc( arr.values.length, 1, arr, 1, 0 );
    t.strictEqual( v, 0.0, 'returns expected value for accessor array with identical elements' );

    // Test NaN case
    x = new Float32Array( [ NaN, 4.0 ] );
    arr = {
        values: x,
        get: function( idx ) { return this.values[ idx ]; }
    };
    v = sstdevyc( arr.values.length, 1, arr, 1, 0 );
    t.strictEqual( isnan( v ), true, 'returns NaN for accessor array with NaN' );

    t.end();
});

tape( 'the function returns NaN for invalid inputs', function test( t ) {
    var x = new Float32Array( [ 1.0, 2.0, 3.0 ] );

    t.strictEqual( isnan( sstdevyc( 0, 0, x, 1, 0 ) ), true, 'returns NaN for N <= 0' );
    t.strictEqual( isnan( sstdevyc( -1, 0, x, 1, 0 ) ), true, 'returns NaN for negative N' );
    t.strictEqual( isnan( sstdevyc( 3, 3, x, 1, 0 ) ), true, 'returns NaN for correction >= N' );
    t.strictEqual( isnan( sstdevyc( 3, -1, x, 1, 0 ) ), true, 'returns NaN for negative correction' );
    t.strictEqual( isnan( sstdevyc( 3, 0, x, 1.5, 0 ) ), true, 'returns NaN for non-integer stride' );
    t.strictEqual( isnan( sstdevyc( 3, 0, x, 1, -1 ) ), true, 'returns NaN for negative offset' );
    t.strictEqual( isnan( sstdevyc( 3, 0, null, 1, 0 ) ), true, 'returns NaN for null input' );

    t.end();
});